uniform float speed : 0.01 .. 2.0 = 0.1;
uniform float tail : 0.05 .. 0.5 = 0.25;
uniform float intensity : 0.0 .. 1.0 = 1.0;

state fixed phase;
state fixed tail_fixed;

void update() {
  phase = fract(phase + fixed(dt * speed));
  tail_fixed = fixed(tail);
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed d = s - phase;
  fixed lit = clamp((tail_fixed - d) * fixed(4.0), fixed(0.0), fixed(1.0));
  fixed h = fixed(0.04) + fixed(0.06) * lit;
  fixed sat = fixed(0.6) + fixed(0.3) * lit;
  return hsv2rgb(h, sat, lit * fixed(intensity));
}
